    "https://www.yz.sdu.edu.cn/2024/shandongdaxue2024nianshuoshiyanjiushengzhaoshengzhuanyemulu.pdf#29#11",
    "https://www.cs.sdu.edu.cn/zsxx/ssyjs.htm",
    "https://www.cs.sdu.edu.cn/system/_content/download.jsp?urltype=news.DownloadAttachUrl&owner=1470795559&wbfileid=15996044#1#1",
    "https://www.istudy.sdu.edu.cn/style/masterprograms/shuoshijisuanjikexueyujishu.pdf#1#1",
    "https://rsc.qd.sdu.edu.cn/PDF/shandongdaxuejisuanjikexueyujishuboshihouliudongzhanjianjie.pdf#1#1"
  ],
  "recommendationNotice": "你已明确目标为山东大学计算机相关专业，因此本方案不再推荐其他院校作为替代或冲刺。后续需重点核实：目标年度招生专业目录中计算机科学与技术、计算机技术等专业是否继续招生，初试科目是否仍为思想政治理论、英语（一）、数学（一）和计算机学科专业基础，复试形式、统考计划人数、报考资格与培养校区安排。历史招生批次和报考条件仅作择校参考，不能替代当年简章；不编造分数线，也不承诺录取。若未来需要按山东地域和历史层次补充备选院校，可再行筛选。",
  "recommendations": [],
  "tasks": [
    {
      "title": "核对山东大学计算机相关专业最新招生专业目录、考试科目和培养校区，建立信息核对清单。",
      "stage": "信息核对与基础启动",
      "dueDate": "2026-10-01"
    },
    {
      "title": "制定英语与数学每日复习时段，优先补语法、长难句和核心词汇，记录起始水平。",
      "stage": "信息核对与基础启动",
      "dueDate": "2026-10-05"
    },
    {
      "title": "完成高等数学预备知识梳理，建立极限、导数、积分错题本。",
      "stage": "信息核对与基础启动",
      "dueDate": "2026-10-10"
    },
    {
      "title": "启动线性代数基础复习，完成矩阵与行列式入门练习。",
      "stage": "信息核对与基础启动",
      "dueDate": "2026-10-15"
    },
    {
      "title": "开始408数据结构基础，完成线性表、栈和队列知识框架。",
      "stage": "数学英语强化与408基础",
      "dueDate": "2026-10-20"
    },
    {
      "title": "英语阅读精读训练，每周完成三篇真题阅读并整理生词和长难句。",
      "stage": "数学英语强化与408基础",
      "dueDate": "2026-10-25"
    },
    {
      "title": "数学强化章节练习，重点突破中值定理、积分应用和基础证明题。",
      "stage": "数学英语强化与408基础",
      "dueDate": "2026-10-30"
    },
    {
      "title": "408计算机组成原理基础，梳理数据表示、运算器和存储系统。",
      "stage": "数学英语强化与408基础",
      "dueDate": "2026-11-04"
    },
    {
      "title": "概率论基础复习，完成随机变量与常见分布练习。",
      "stage": "408与真题专项",
      "dueDate": "2026-11-09"
    },
    {
      "title": "408操作系统基础，整理进程、内存和文件系统核心概念。",
      "stage": "408与真题专项",
      "dueDate": "2026-11-14"
    },
    {
      "title": "英语写作与小三项训练，积累模板并完成两篇作文。",
      "stage": "408与真题专项",
      "dueDate": "2026-11-19"
    },
    {
      "title": "数学真题分题型训练，建立错题归因与限时训练记录。",
      "stage": "408与真题专项",
      "dueDate": "2026-11-24"
    },
    {
      "title": "408计算机网络基础，梳理分层模型与TCP/IP重点。",
      "stage": "真题专项与弱项突破",
      "dueDate": "2026-11-29"
    },
    {
      "title": "全真模拟一，按考试时段完成数学与408，复盘失分点。",
      "stage": "真题专项与弱项突破",
      "dueDate": "2026-12-04"
    },
    {
      "title": "全真模拟二，完成英语、政治与专业课模拟，调整答题节奏。",
      "stage": "全真模拟与冲刺调整",
      "dueDate": "2026-12-10"
    },
    {
      "title": "考前最后梳理：核对准考证与考场信息，复习错题和高频公式，保持作息。",
      "stage": "全真模拟与冲刺调整",
      "dueDate": "2026-12-18"
    }
  ]
}

